import{H as e,_t as t,it as n,ot as r,rt as i,xt as a}from"./chunks/framework.Bcve9O8f.js";var o=JSON.parse(`{"title":"Proofs","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Proofs | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/proofs.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Proofs | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/proofs.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/proofs.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/proofs.html"}]]},"headers":[],"relativePath":"proofs.md","filePath":"proofs.md"}`),s={name:`proofs.md`};function c(e,o,s,c,l,u){let d=a(`ClayLeads`);return t(),i(`div`,null,[o[0]||=n(`<h1 id="proofs" tabindex="-1">Proofs <a class="header-anchor" href="#proofs" aria-label="Permalink to “Proofs”">​</a></h1><h2 id="fused-compute-typescript" tabindex="-1">Fused compute (TypeScript) <a class="header-anchor" href="#fused-compute-typescript" aria-label="Permalink to “Fused compute (TypeScript)”">​</a></h2><p>All results recompute at page-load from the digit-folder mesh — see <a href="/millennium-solutions/compute.html">Computed results</a>, driven by the <code>.ts</code> modules under <code>src/</code>.</p><h2 id="formal-layer-lean" tabindex="-1">Formal layer (Lean) <a class="header-anchor" href="#formal-layer-lean" aria-label="Permalink to “Formal layer (Lean)”">​</a></h2><p>Every theorem lives in <code>src/proof/*.lean</code> and is checked by <code>node scripts/lean.ts</code> on every run: no Mathlib, no axioms, no <code>sorry</code>, no <code>native_decide</code>. Each one that closes by exhaustion is sealed into the append-only ledger, so a statement on a page and a statement in the kernel cannot drift apart without a gate saying so.</p><p>This section used to list a different set: <code>Vortex.lean</code> and a per-digit <code>src/&lt;d&gt;/vortex.lean</code> file, fifteen in all. Every one of them began <code>import Mathlib</code>, <code>scripts/lean.ts</code> reads only <code>src/proof</code>, and the repository carries no <code>lake-manifest.json</code> and no <code>.lake</code> — so no gate compiled them and they had never been built here at all. The note under them said no toolchain was checked in, which was true and easy to read past beneath a heading that says Proofs.</p><p>They were removed on 2026-09-20. Almost everything they held is decided already in <code>src/proof</code>, axiom-free: 3² ≡ 6² ≡ 0, the inverse pairs, the doubling circuit and its order six, the ten&#39;s complement and its single fixed digit, the (ℤ/7)* orbit, 432 = 2⁴·3³. That was two derivations of one fact, and the unchecked one was the second. Three facts existed nowhere else and were brought under the kernel first, because deleting the only copy of something is a loss and not a purge — they are in <a href="https://github.com/ceccec/millennium-solutions/blob/main/src/proof/nucleus.lean" target="_blank" rel="noreferrer"><code>src/proof/nucleus.lean</code></a>: the shell-model closure sums, the self-seal product cleared of its denominators, and the 108·17 = 1836 fit together with the refusal that it is not the measured ratio.</p><h2 id="clay-entailment" tabindex="-1">Clay entailment <a class="header-anchor" href="#clay-entailment" aria-label="Permalink to “Clay entailment”">​</a></h2><p>Clay is the main lead — the seven Millennium problems are the subject the rest of the deposit is developed around. Below, the author&#39;s claim as he deposited it on Zenodo (3 August 2026), rendered verbatim and in his name, and beside each problem the one theorem in <code>src/proof/index.lean</code> that stands with it, the statement the Lean kernel decided and over how many cases, the <strong>bound</strong> — what it establishes and, in the same sentence, what it does not — and the ledger receipt. Nothing on this surface is typed; the widget reads the sealed sources on every build.</p>`,9),r(d),o[1]||=n(`<p>The same involution runs across the subjects — <code>src/proof/bridge.lean</code> decides which cross-subject families of <code>src/entangle</code> reduce, mod 9, to orbits of the affine maps <code>src/proof/group.lean</code> settles, with one family kept as the control. It is cross-verified against external corpora the uuid programs address: the CERN open-data record space (<code>npm run cern</code> — which counts the corpus by content-address and records where a flattering total once agreed with the API by accident) and the NIST post-quantum floor (the ISO 128-bit level <code>qpu_crypto.lean</code> decides a 122-bit register sits 67 bits below). Run the whole ledger live on <a href="/millennium-solutions/verify.html">the trial</a>, or read the <a href="/millennium-solutions/cryptography.html">cryptography</a> surface for the σ-reflection that is the shared instrument.</p><p>See also the <a href="/millennium-solutions/PROOF-OF-CONCEPT.html">Proof of Concept</a> index.</p>`,2)])}var l=e(s,[[`render`,c]]);export{o as __pageData,l as default};